<?php if (!defined('ABSPATH')) exit; get_header(); ?><main class="bv-container bv-section"><h1><?php echo esc_html(get_bloginfo('name')); ?></h1><?php if(have_posts()): while(have_posts()):the_post(); ?><article><h2><a href="<?php echo esc_url(get_permalink()); ?>"><?php the_title(); ?></a></h2><?php the_excerpt(); ?></article><?php endwhile; endif; ?></main><?php get_footer(); ?>